package com.loja.checkout.dominio;

import java.math.BigDecimal;

/**
 * Regiao do cliente. O seguro do envio e sempre a mesma conta - a porcentagem
 * sobre o valor dos produtos - so a porcentagem muda de regiao para regiao.
 */
public enum Regiao {

    SUDESTE("0.010"),
    SUL("0.010"),
    CENTRO_OESTE("0.015"),
    NORTE("0.025"),
    NORDESTE("0.020");

    private final BigDecimal taxaSeguro;

    Regiao(String taxaSeguro) {
        this.taxaSeguro = new BigDecimal(taxaSeguro);
    }

    public BigDecimal seguro(BigDecimal subtotalProdutos) {
        return Centavos.percentual(subtotalProdutos, taxaSeguro);
    }
}
EOF
cat > dominio/NivelClube.java <<'EOF'
package com.loja.checkout.dominio;

import java.math.BigDecimal;

/** Nivel do cliente no clube da loja: cada nivel tem seu conjunto de vantagens. */
public enum NivelClube {

    BRONZE {
        @Override
        public BigDecimal creditoProximaCompra(BigDecimal subtotalProdutos) {
            return Centavos.ZERO;
        }

        @Override
        public boolean isentaFrete() {
            return false;
        }

        @Override
        public boolean temBrinde(BigDecimal subtotalProdutos) {
            return false;
        }
    },

    PRATA {
        @Override
        public BigDecimal creditoProximaCompra(BigDecimal subtotalProdutos) {
            return Centavos.percentual(subtotalProdutos, new BigDecimal("0.02"));
        }

        @Override
        public boolean isentaFrete() {
            return false;
        }

        @Override
        public boolean temBrinde(BigDecimal subtotalProdutos) {
            return false;
        }
    },

    OURO {
        private static final BigDecimal MINIMO_BRINDE = new BigDecimal("500.00");

        @Override
        public BigDecimal creditoProximaCompra(BigDecimal subtotalProdutos) {
            return Centavos.percentual(subtotalProdutos, new BigDecimal("0.05"));
        }

        @Override
        public boolean isentaFrete() {
            return true;
        }

        @Override
        public boolean temBrinde(BigDecimal subtotalProdutos) {
            return subtotalProdutos.compareTo(MINIMO_BRINDE) > 0;
        }
    };

    /** Credito guardado para a proxima compra, sobre o valor dos produtos. */
    public abstract BigDecimal creditoProximaCompra(BigDecimal subtotalProdutos);

    /** Se o nivel nunca paga frete. */
    public abstract boolean isentaFrete();

    /** Se o pedido vai com brinde. */
    public abstract boolean temBrinde(BigDecimal subtotalProdutos);
}
EOF
